let capMb = 150.0;
let resetAt = bin(now() - 14h, 1d) + 14h;
let today = toscalar(Usage | where TimeGenerated >= resetAt and IsBillable | summarize sum(Quantity));
let stops = toscalar(_LogOperation | where TimeGenerated > ago(30d) and Category == "Ingestion" and Detail has "OverQuota" | count);
let lastStop = toscalar(_LogOperation | where TimeGenerated > ago(30d) and Category == "Ingestion" and Detail has "OverQuota" | summarize max(TimeGenerated));
print Kennzahl = pack_array("Logs seit Reset (MB)", "Tageslimit belegt (%)", "Limit erreicht (30 Tage)", "Zuletzt erreicht"),
      Wert = pack_array(tostring(round(today, 1)), tostring(round(100 * today / capMb, 0)), tostring(stops), iff(isnull(lastStop), "nie", format_datetime(datetime_utc_to_local(lastStop, "Europe/Zurich"), "dd.MM. HH:mm")))
| mv-expand Kennzahl to typeof(string), Wert to typeof(string)

let runs = AppTraces
| where TimeGenerated > ago(30d)
| where Message matches regex @"^Forecast run [0-9a-fA-F-]+: "
| project TimeGenerated, Status = tostring(Properties.Status);
let lastOk = toscalar(runs | where Status in ("Succeeded", "PartiallySucceeded") | summarize max(TimeGenerated));
let lastRun = runs | top 1 by TimeGenerated;
let next = toscalar(AppTraces | where TimeGenerated > ago(2d) and Message startswith "Next forecast run at" | top 1 by TimeGenerated | project tostring(Properties.NextRun));
lastRun
| project Kennzahl = pack_array("Letzter Lauf", "Status", "Letzter brauchbarer Lauf vor (h)", "Nächster Lauf"),
          Wert = pack_array(format_datetime(datetime_utc_to_local(TimeGenerated, "Europe/Zurich"), "dd.MM. HH:mm"), Status, tostring(round((now() - lastOk) / 1h, 1)), substring(next, 0, 16))
| mv-expand Kennzahl to typeof(string), Wert to typeof(string)
